custom_css:
/* 只隐藏所有真实滚动容器的滚动条外观；不改变 overflow、触摸、键盘或 range 控件。 */
* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

*::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
}

/*
 * 晴屿 · SillyTavern 1.14.0 夏日主题
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */
@font-face {
    font-family: "Zhuque Fangsong";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/zhuquefangsong/zhuquefangsong.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Special Elite";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/special-elite/SpecialElite-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --theme-surface: #fffdf5;
    --theme-surface-muted: #eef7f4;
    --theme-surface-disabled: #eaf6f3;
    --theme-text-primary: #183b5b;
    --theme-text-secondary: #557487;
    --theme-text-disabled: #557487;
    --theme-border: #9fc8cf;
    --theme-border-strong: #4c91aa;
    --theme-focus-ring: #e3b63f;
    --theme-accent: #3f8fac;
    --theme-accent-alt: #edc44d;
    --theme-accent-soft: #d9eff0;
    --theme-quote-muted: #9a7b42;
    --theme-code-overflow: auto;
    --theme-user-surface: #fff2bf;
    --theme-info: #5c9db4;
    --theme-success: #5d9576;
    --theme-warning: #cc8a2f;
    --theme-error: #b95851;
    --theme-overlay: #fffdf8;
    --theme-opacity-disabled: 0.82;
    --theme-shadow: none;
    --theme-font-body: "Special Elite", "Zhuque Fangsong", "FangSong", "STFangsong", serif;
    --theme-font-ui: "Zhuque Fangsong", "Microsoft YaHei UI", system-ui, sans-serif;
    --theme-font-mono: "Special Elite", "Cascadia Mono", Consolas, monospace;
    --theme-toolbar-sprite: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/93c2a293a8e8a3a5ba2d44898a1973e532fc5088/assets/%E6%99%B4%E5%B1%BF/qingyu-toolbar-keepsakes.png");
    --theme-avatar-size: 72px;
    --theme-radius-small: 8px;
    --theme-radius-medium: 16px;
    --theme-radius-large: 24px;
    --topBarIconSize: 52px;
    --topBarBlockPadding: 20px;
    --topBarBlockSize: 72px;
    --bottomFormIconSize: 36px;
    --bottomFormBlockPadding: 12px;
    --bottomFormBlockSize: 48px;
    --mainFontFamily: var(--theme-font-body);
}

body,
#bg1,
#bg_custom {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    background-image:
        radial-gradient(circle at 8% 12%, rgb(237 196 77 / 18%) 0 3px, transparent 4px),
        radial-gradient(circle at 92% 22%, rgb(63 143 172 / 16%) 0 4px, transparent 5px),
        linear-gradient(135deg, rgb(238 247 244 / 96%), rgb(255 253 245 / 98%) 48%, rgb(255 242 191 / 82%));
    background-attachment: fixed;
    font-family: var(--theme-font-body);
}

::selection {
    color: var(--theme-text-primary);
    background-color: var(--theme-accent-soft);
}

/* 主聊天几何：保留官方 .mes Flex、节点顺序、事件与滚动。 */
#chat .mes:not([is_system="true"]) {
    width: min(calc(100% - 24px), 1120px);
    margin-inline: auto;
}

#chat .mes:not([is_system="true"]) > .mes_block {
    flex: 1 1 0;
    width: auto;
    min-width: 0;
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper {
    flex: 0 0 var(--theme-avatar-size);
    width: var(--theme-avatar-size);
    margin-inline-end: 16px;
}

#chat .mes[is_user="true"] + .mes[is_user="false"][is_system="false"] {
    margin-top: 0;
}

#chat :is(.mes_text, .mes_reasoning) :is(img, video, table, pre) {
    max-width: 100%;
}

#chat :is(.mes_text, .mes_reasoning) :is(pre, .table-container) {
    overflow-x: auto;
}

/* 晴屿：长正文是一张连续、居中的海盐纸页。 */
#chat :is(.mes_text, .mes_reasoning) {
    color: var(--theme-text-primary);
    font-family: var(--theme-font-body);
    font-size: 1em;
    font-weight: 400;
    line-height: 1.92;
    letter-spacing: 0.035em;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
    width: min(100%, 58ch);
    padding: 10px 18px;
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-user-surface);
    font-size: 0.98em;
    line-height: 1.7;
}

#chat .mes[is_user="true"] + .mes[is_user="false"][is_system="false"] .mes_text {
    width: min(100%, 76ch);
    margin-inline: auto;
    padding: clamp(22px, 3vw, 38px) clamp(20px, 4vw, 48px);
    color: var(--theme-text-primary);
    border: 0;
    background-color: var(--theme-surface);
    background-image: none;
}

#chat .mes_text > p {
    margin-block: 0 1.05em;
}

#chat .mes_text > p:first-child {
    font-size: 1.06em;
    line-height: 1.98;
}

#chat :is(.mes_text, .mes_reasoning) :is(h1, h2, h3, h4, h5, h6) {
    color: var(--theme-accent);
    font-family: var(--theme-font-ui);
    font-weight: 400;
    line-height: 1.4;
    letter-spacing: 0.06em;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
    margin: 1.25em 0;
    padding: 14px 20px;
    color: var(--theme-text-primary);
    border-inline-start: 4px solid var(--theme-accent-alt);
    background-color: var(--theme-surface-muted);
    font-size: 1.06em;
}

#chat :is(.mes_text, .mes_reasoning) q {
    color: var(--theme-quote-muted);
}

#chat :is(.mes_text, .mes_reasoning) :is(strong, b) {
    color: var(--theme-accent);
    font-weight: 400;
}

#chat :is(.mes_text, .mes_reasoning) li::marker {
    color: var(--theme-accent-alt);
}

#chat :is(.mes_text, .mes_reasoning) hr {
    height: 1px;
    margin-block: 1.5em;
    border: 0;
    background-color: var(--theme-border);
}

#chat :is(.mes_text, .mes_reasoning) pre {
    overflow-x: var(--theme-code-overflow);
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface-muted);
    box-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) pre code.hljs {
    color: var(--theme-text-primary);
    background: var(--theme-surface-muted) !important;
    background-image: none !important;
    text-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) code:not(pre code) {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    background-color: var(--theme-surface-muted);
    text-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) pre code.hljs {
    opacity: 1;
}

#chat :is(.mes_text, .mes_reasoning) pre > code.hljs :is(.hljs-comment, .hljs-quote, .hljs-meta) {
    color: var(--theme-text-secondary);
    opacity: 1;
    text-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) pre > code.hljs :is(.hljs-keyword, .hljs-selector-tag, .hljs-title, .hljs-section, .hljs-string, .hljs-addition, .hljs-attribute, .hljs-number, .hljs-literal, .hljs-symbol) {
    color: var(--theme-accent);
    opacity: 1;
    text-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) pre > code.hljs::selection,
#chat :is(.mes_text, .mes_reasoning) pre > code.hljs *::selection {
    color: var(--theme-text-primary);
    background-color: var(--theme-accent-soft);
}

#chat :is(.mes_text, .mes_reasoning) pre > code.hljs > .code-copy {
    color: var(--theme-accent);
    background-color: var(--theme-surface);
    opacity: 1;
    filter: none;
    box-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) pre > code.hljs > .code-copy:hover {
    color: var(--theme-text-primary);
    background-color: var(--theme-accent-soft);
    opacity: 1;
    filter: none;
    box-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) pre > code.hljs > .code-copy:focus-visible {
    color: var(--theme-accent);
    background-color: var(--theme-surface);
    outline: 2px solid var(--theme-focus-ring);
    opacity: 1;
    filter: none;
    box-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) :is(pre, code) {
    font-family: var(--theme-font-mono);
}

#chat :is(.mes_text, .mes_reasoning) table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
    border-color: var(--theme-border);
}

#chat :is(.mes_text, .mes_reasoning) img {
    max-width: 100%;
    height: auto;
    border-radius: var(--theme-radius-small);
}

/* W01 · 主聊天、相邻楼层、真实头像与消息状态。 */
#sheld {
    border-inline: 1px solid var(--theme-border);
    background-color: var(--theme-surface-muted);
}

#chat {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    background-image:
        radial-gradient(circle at 4% 18%, rgb(63 143 172 / 8%) 0 3px, transparent 4px),
        radial-gradient(circle at 96% 72%, rgb(237 196 77 / 9%) 0 4px, transparent 5px);
}

#chat .mes:not([is_system="true"]) {
    margin-block: 14px;
    padding: 18px 22px;
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-large);
    background-color: var(--theme-surface);
}

#chat .mes[is_user="true"] {
    margin-bottom: 0;
    border-bottom: 0;
    border-radius: var(--theme-radius-large) var(--theme-radius-large) 0 0;
    background-color: var(--theme-surface-muted);
}

#chat .mes[is_user="true"] + .mes[is_user="false"][is_system="false"] {
    padding-top: 10px;
    border-top: 1px dashed var(--theme-border-strong);
    border-radius: 0 0 var(--theme-radius-large) var(--theme-radius-large);
}

#chat .mes:not([is_system="true"]) .avatar,
#chat .mes:not([is_system="true"]) .avatar img {
    width: var(--theme-avatar-size);
    height: var(--theme-avatar-size);
    border-radius: 50%;
}

#chat .mes:not([is_system="true"]) .avatar {
    overflow: hidden;
    border: 3px solid var(--theme-surface);
    outline: 2px solid var(--theme-border-strong);
    outline-offset: 2px;
    background-color: var(--theme-surface);
}

#chat .mes[is_user="true"] .avatar {
    outline-color: var(--theme-accent-alt);
}

#chat .mes:not([is_system="true"]) .avatar img {
    object-fit: cover;
    object-position: center;
}

#chat .ch_name {
    min-height: 0;
    margin-bottom: 8px;
    color: var(--theme-text-primary);
    border-bottom: 1px solid var(--theme-border);
    font-family: var(--theme-font-ui);
}

#chat .name_text {
    color: var(--theme-accent);
    font-family: var(--theme-font-ui);
    font-weight: 400;
    letter-spacing: 0.08em;
}

#chat :is(.timestamp, .mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    color: var(--theme-text-secondary);
    font-family: var(--theme-font-mono);
    font-size: 0.78em;
}

#chat .mes[is_system="true"] {
    width: min(88%, 780px);
    margin: 8px auto;
    color: var(--theme-text-secondary);
    border: 1px dashed var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface-muted);
}

#chat .mes_reasoning_details {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface-muted);
}

#chat .mes_reasoning_details:not([open]) {
    background-color: var(--theme-surface-muted);
}

#chat .mes_reasoning_details[open] {
    border-color: var(--theme-border-strong);
    background-color: var(--theme-surface);
}

#chat .mes_reasoning_details[data-state="thinking"] {
    color: var(--theme-info);
    border-color: var(--theme-info);
    background-color: var(--theme-accent-soft);
}

#chat .mes_reasoning_details[data-state="done"],
#chat .mes_reasoning_details[data-state="hidden"] {
    color: var(--theme-text-primary);
    border-color: var(--theme-success);
    background-color: var(--theme-surface-muted);
}

#chat .mes_reasoning_details:focus-visible {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 2px;
}

#chat .mes_reasoning_details .mes_reasoning,
#chat .mes_reasoning_details .mes_reasoning_header_title {
    color: var(--theme-text-primary);
}

#chat .mes_reasoning_details .mes_reasoning_arrow {
    color: var(--theme-accent);
    filter: none;
}

#chat .mes_buttons :is(.mes_button, .menu_button),
#chat .extraMesButtons > div,
#chat .mes_reasoning_actions :is(.mes_button, .edit_button) {
    color: var(--theme-accent);
    opacity: 1;
    filter: none;
}

#chat .mes_buttons :is(.mes_button, .menu_button):hover,
#chat .extraMesButtons > div:hover,
#chat .mes_reasoning_actions :is(.mes_button, .edit_button):hover {
    color: var(--theme-accent-alt);
}

#chat .mes_buttons :is(.mes_button, .menu_button):disabled,
#chat .extraMesButtons > div[aria-disabled="true"],
#chat .mes_reasoning_actions :is(.mes_button, .edit_button):disabled {
    color: var(--theme-text-disabled);
    opacity: var(--theme-opacity-disabled);
    filter: none;
}

#chat .mes_buttons :is(.mes_button, .menu_button):focus-visible,
#chat .extraMesButtons > div:focus-visible,
#chat .mes_reasoning_actions :is(.mes_button, .edit_button):focus-visible {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 2px;
}

#chat .mes_edit_buttons .edit_button {
    color: var(--theme-accent);
    filter: none;
}

/* 消息编辑工具栏：替换原生 menu_button 灰底、灰阶与父级投影。 */
#chat .mes .mes_edit_buttons {
    filter: none;
}

#chat .mes .mes_edit_buttons > .menu_button {
    color: var(--theme-accent);
    border-color: var(--theme-border-strong);
    background-color: var(--theme-accent-soft);
    background-image: none;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes .mes_edit_buttons > .menu_button:not(.disabled):not([disabled]):hover {
    color: var(--theme-accent-alt);
    border-color: var(--theme-accent-alt);
    background-color: var(--theme-surface-muted);
    opacity: 1;
    filter: none;
}

#chat .mes .mes_edit_buttons > .mes_edit_done.menu_button {
    color: var(--theme-surface);
    border-color: var(--theme-success);
    background-color: var(--theme-success);
}

#chat .mes .mes_edit_buttons > .mes_edit_delete.menu_button {
    color: var(--theme-error);
}

#chat .mes .mes_edit_buttons > .mes_edit_cancel.menu_button {
    color: var(--theme-surface);
    border-color: var(--theme-error);
    background-color: var(--theme-error);
}

#chat .mes .mes_edit_buttons > .menu_button:is(.disabled, [disabled]) {
    color: var(--theme-text-disabled);
    border-color: var(--theme-border);
    background-color: var(--theme-surface-disabled);
    opacity: var(--theme-opacity-disabled);
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

/* 消息进入编辑状态后，官方会给真实 textarea 写入 black50a。 */
#chat .mes .mes_text > textarea#curEditTextarea.edit_textarea {
    color: var(--theme-text-primary);
    caret-color: var(--theme-accent);
    border: 1px solid var(--theme-border-strong);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface-muted);
    background-image: none;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes .mes_text > textarea#curEditTextarea.edit_textarea:focus-visible {
    border-color: var(--theme-focus-ring);
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 1px;
}

#chat .mes_buttons .mes_button[title*="More"],
#chat .mes_buttons .mes_button[title*="更多"] {
    color: var(--theme-accent-alt);
    filter: none;
}

/* W02 · 九个原生入口只重绘触发器，不修改 .drawer 与内容层几何。 */
#top-bar {
    height: 0;
    color: var(--theme-text-primary);
    border: 0;
    background-color: transparent;
    background-image: none;
    box-shadow: none;
    pointer-events: none;
}

#top-settings-holder {
    margin-top: 0;
    color: var(--theme-text-primary);
    border: 0;
    background-color: var(--theme-surface);
    background-image: linear-gradient(180deg, rgb(255 253 245 / 98%), rgb(217 239 240 / 52%));
    box-shadow: none;
}

#top-settings-holder > .drawer > .drawer-toggle {
    min-inline-size: 0;
    height: var(--topBarBlockSize);
    padding-inline: 3px;
    color: var(--theme-text-primary);
    background-color: transparent;
}

#top-settings-holder > .drawer > .drawer-toggle .drawer-icon {
    inline-size: var(--topBarIconSize);
    height: var(--topBarIconSize);
    padding: 0;
    color: var(--theme-accent);
    background-image: var(--theme-toolbar-sprite);
    background-repeat: no-repeat;
    background-size: 300% 300%;
    font-size: 10px;
    line-height: var(--topBarIconSize);
    opacity: 1;
    filter: none;
}

/* 小物已承担可见图标：只关闭 Font Awesome 的旧 ::before 生成层。 */
#top-settings-holder > .drawer > .drawer-toggle .drawer-icon::before {
    display: none;
}

#top-settings-holder > .drawer > .drawer-toggle:hover {
    color: var(--theme-accent);
    background-color: var(--theme-surface-muted);
}

#top-settings-holder > .drawer > .drawer-toggle:hover .drawer-icon {
    color: var(--theme-accent-alt);
}

#top-settings-holder > .drawer > .drawer-toggle:has(.openIcon),
#top-settings-holder > .drawer > .drawer-toggle[aria-expanded="true"] {
    color: var(--theme-accent);
    background-color: var(--theme-accent-soft);
}

#top-settings-holder > .drawer > .drawer-toggle:focus-visible {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: -2px;
}

#top-settings-holder > .drawer > .drawer-toggle[aria-disabled="true"] {
    color: var(--theme-text-disabled);
    background-color: var(--theme-surface-disabled);
    opacity: var(--theme-opacity-disabled);
}

#ai-config-button > .drawer-toggle .drawer-icon { background-position: 0% 0%; }
#sys-settings-button > .drawer-toggle .drawer-icon { background-position: 50% 0%; }
#advanced-formatting-button > .drawer-toggle .drawer-icon { background-position: 100% 0%; }
#WI-SP-button > .drawer-toggle .drawer-icon { background-position: 0% 50%; }
#user-settings-button > .drawer-toggle .drawer-icon { background-position: 50% 50%; }
#backgrounds-button > .drawer-toggle .drawer-icon { background-position: 100% 50%; }
#extensions-settings-button > .drawer-toggle .drawer-icon { background-position: 0% 100%; }
#persona-management-button > .drawer-toggle .drawer-icon { background-position: 50% 100%; }
#rightNavHolder > .drawer-toggle .drawer-icon { background-position: 100% 100%; }

/* W03 · 输入页脚、菜单、魔法棒、发送与停止。 */
#send_form {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border-strong);
    border-radius: var(--theme-radius-medium);
    background-color: var(--theme-surface);
    background-image: linear-gradient(90deg, rgb(217 239 240 / 45%), transparent 18%, transparent 82%, rgb(255 242 191 / 46%));
}

#send_form:focus-within {
    border-color: var(--theme-focus-ring);
}

#nonQRFormItems {
    align-items: flex-end;
    min-inline-size: 0;
}

#leftSendForm,
#rightSendForm {
    flex: 0 0 auto;
    min-inline-size: 0;
}

#send_textarea {
    flex: 1 1 0;
    inline-size: 0;
    min-inline-size: 0;
    max-inline-size: 100%;
    box-sizing: border-box;
    margin: 0;
    padding: 8px 12px;
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface);
    font-family: var(--theme-font-body);
    font-size: 16px;
    line-height: 1.4;
}

#send_textarea:disabled {
    color: var(--theme-text-disabled);
    background-color: var(--theme-surface-disabled);
    opacity: var(--theme-opacity-disabled);
}

#send_textarea:focus-visible {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 1px;
}

#send_textarea::placeholder {
    color: var(--theme-text-secondary);
    font-size: 16px;
    opacity: 1;
}

#send_textarea:disabled::placeholder {
    color: var(--theme-text-disabled);
    opacity: var(--theme-opacity-disabled);
}

#options_button,
#extensionsMenuButton {
    color: var(--theme-accent);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-accent-soft);
    filter: none;
}

#WandAndExtensionsMenuButton {
    color: var(--theme-accent-alt);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface-muted);
    filter: none;
}

