    box-shadow: none;
    text-shadow: none;
    filter: none;
}

#rm_extensions_block :is(#extensions_settings, #extensions_settings2) .inline-drawer-toggle.inline-drawer-header:hover {
    color: var(--theme-accent);
    border-color: var(--theme-border-strong);
    background-color: var(--theme-accent-soft);
    background-image: linear-gradient(var(--theme-accent-soft), var(--theme-accent-soft));
    filter: none;
}

#rm_extensions_block :is(#extensions_settings, #extensions_settings2) .inline-drawer-toggle.inline-drawer-header .inline-drawer-icon {
