/* W13 · Persona。 */
#PersonaManagement {
    color: var(--theme-text-primary);
    background-color: var(--theme-overlay);
}

#PersonaManagement .avatar-container {
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface);
}

#PersonaManagement .avatar-container:hover {
    border-color: var(--theme-border-strong);
    background-color: var(--theme-accent-soft);
}

#PersonaManagement .avatar-container.selected {
    border-color: var(--theme-accent);
    background-color: var(--theme-user-surface);
}

/* W12 · 角色与群组；编辑页从真实 #rm_ch_create_block 节点延展。 */
#right-nav-panel {
    color: var(--theme-text-primary);
    background-color: var(--theme-overlay);
}

#right-nav-panel :is(.character_select, .group_select, .avatar-container) {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface);
}

#right-nav-panel :is(.character_select, .group_select, .avatar-container):hover {
    border-color: var(--theme-border-strong);
    background-color: var(--theme-accent-soft);
}

#right-nav-panel :is(.character_select, .group_select):is(.selected, .character_selected) {
    border-color: var(--theme-accent);
    background-color: var(--theme-user-surface);
}

#right-nav-panel :is(.character_select, .group_select, .bogus_folder_select):focus-visible {
    border-color: var(--theme-focus-ring);
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 1px;
}

#right-nav-panel #rm_print_characters_block :is(.character_select, .group_select, .bogus_folder_select) .avatar {
    box-shadow: none;
    filter: none;
}

#right-nav-panel #rm_print_characters_block .entity_block.useless {
    color: var(--theme-text-disabled);
    background-color: var(--theme-surface-disabled);
    opacity: var(--theme-opacity-disabled);
    filter: none;
}

/* 角色筛选键由脚本写入灰色内联 background-color，因此在真实筛选根内替换。 */
#right-nav-panel #rm_characters_block .rm_tag_filter .tag {
    color: var(--theme-accent) !important;
    border-color: var(--theme-border) !important;
    background-color: var(--theme-accent-soft) !important;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#right-nav-panel #rm_characters_block .rm_tag_filter .tag:hover {
    color: var(--theme-text-primary) !important;
    border-color: var(--theme-border-strong) !important;
    background-color: var(--theme-user-surface) !important;
    opacity: 1;
    filter: none;
}

#right-nav-panel #rm_characters_block .rm_tag_filter .tag:focus-visible {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 2px;
}

#right-nav-panel #rm_characters_block .rm_tag_filter .tag.selected {
    color: var(--theme-surface) !important;
    border-color: var(--theme-accent) !important;
    background-color: var(--theme-accent) !important;
    opacity: 1 !important;
    filter: none !important;
}

#right-nav-panel #rm_characters_block .rm_tag_filter .tag.excluded {
    color: var(--theme-error) !important;
    border-color: var(--theme-error) !important;
    background-color: var(--theme-surface-disabled) !important;
    opacity: 1 !important;
    filter: none !important;
}

#right-nav-panel #rm_characters_block .rm_tag_filter .tag.excluded::after {
    color: var(--theme-error);
    text-shadow: none;
}

/* 角色卡标签同样带脚本内联色，只在角色列表卡片内改为晴屿色。 */
#right-nav-panel #rm_print_characters_block .tags_inline {
    opacity: 1;
    filter: none;
}

#right-nav-panel #rm_print_characters_block .tags_inline .tag {
    color: var(--theme-text-secondary) !important;
    border-color: var(--theme-border) !important;
    background-color: var(--theme-accent-soft) !important;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#right-nav-panel :is(#tagList, .tags, .tags_inline) .tag {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    background-color: var(--theme-surface-muted);
}

#right-nav-panel :is(#tagList, .tags, .tags_inline) .tag .tag_remove { color: var(--theme-accent); }

#right-nav-panel #rm_ch_create_block #spoiler_free_desc > .inline-drawer-toggle.inline-drawer-header.standoutHeader {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-small);
    background-color: var(--theme-surface-muted);
    background-image: linear-gradient(var(--theme-surface-muted), var(--theme-surface-muted));
    box-shadow: none;
    text-shadow: none;
    filter: none;
}

#right-nav-panel #rm_ch_create_block :is(#description_div, #first_message_div, #personality_div, #scenario_div, #mes_example_div) {
    color: var(--theme-text-primary);
    border-bottom: 1px solid var(--theme-border);
    background-color: transparent;
}

#right-nav-panel #rm_ch_create_block :is(#character_name_pole, #tagInput, #description_textarea, #first_message_textarea, #personality_textarea, #scenario_pole, #mes_example_textarea) {
    color: var(--theme-text-primary);
    border-color: var(--theme-border);
    background-color: var(--theme-surface);
    box-shadow: none;
    text-shadow: none;
}

#right-nav-panel #rm_ch_create_block #delete_button.red_button {
    color: var(--theme-accent);
    border: 1px solid var(--theme-border);
    background-color: var(--theme-surface-muted) !important;
    box-shadow: none;
    text-shadow: none;
    filter: none;
}

#right-nav-panel #rm_ch_create_block #delete_button.red_button:hover {
    color: var(--theme-text-primary);
    border-color: var(--theme-border-strong);
    background-color: var(--theme-accent-soft) !important;
}

/* W07 · 弹窗、Toast、确认与临时界面。 */
:is(.popup, dialog, .popup-content) {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-border-strong);
    border-radius: var(--theme-radius-medium);
    background-color: var(--theme-overlay);
}

:is(.popup, dialog, .popup-content) :is(button, .menu_button) {
    color: var(--theme-accent);
    border: 1px solid var(--theme-border);
    background-color: var(--theme-surface);
}

#toast-container .toast-info {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-info);
    background-color: var(--theme-surface-muted);
    background-image: none;
}

#toast-container .toast-success {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-success);
    background-color: var(--theme-surface);
    background-image: none;
}

#toast-container .toast-warning {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-warning);
    background-color: var(--theme-user-surface);
    background-image: none;
}

#toast-container .toast-error {
    color: var(--theme-text-primary);
    border: 1px solid var(--theme-error);
    background-color: var(--theme-accent-soft);
    background-image: none;
}

#toast-container :is(.toast-loading, .toast-progress) {
    color: var(--theme-info);
    border-color: var(--theme-info);
    background-color: var(--theme-surface-muted);
}

#toast-container :is(.toast-message, .toast-title) {
    color: var(--theme-text-primary);
}

#toast-container :is(.toast-icon, .toast-close-button, .fa-solid) {
    color: var(--theme-accent);
    filter: none;
}

#toast-container :is(button, a, .toast-close-button) {
    color: var(--theme-accent);
    background-color: transparent;
}

#toast-container :is(button, a, .toast-close-button):focus-visible {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 2px;
}

/* 390px 独立母版：保留原生滚动、抽屉关闭和全部九个入口。 */
@media (max-width: 700px) {
    :root {
        --theme-avatar-size: 54px;
        --topBarIconSize: 36px;
        --topBarBlockPadding: 12px;
        --topBarBlockSize: 48px;
        --bottomFormIconSize: 32px;
        --bottomFormBlockPadding: 10px;
        --bottomFormBlockSize: 42px;
    }

    #chat .mes:not([is_system="true"]) {
        width: calc(100% - 10px);
        margin-block: 8px;
        padding: 12px 10px;
        border-radius: var(--theme-radius-medium);
        flex-direction: column;
        align-items: stretch;
        box-sizing: border-box;
    }

    #chat .mes:not([is_system="true"]) > .mesAvatarWrapper {
        align-self: center;
        margin-inline: auto;
    }

    #chat .mes:not([is_system="true"]) > .mes_block {
        flex: 0 1 auto;
        inline-size: 100%;
        min-inline-size: 0;
        max-inline-size: 100%;
        block-size: auto;
        padding-inline: 0;
        overflow-y: visible;
    }

    #chat .mes[is_user="true"] + .mes[is_user="false"][is_system="false"] .mes_text {
        width: 100%;
        padding: 18px 14px;
    }

    #chat .mes:not([is_system="true"]) > .mes_block > .mes_text {
        inline-size: min(100%, 76ch);
        max-inline-size: 100%;
        margin-inline: auto !important;
        padding-inline: 14px !important;
        box-sizing: border-box;
    }

    #chat :is(.mes_text, .mes_reasoning) {
        font-size: 0.96em;
        line-height: 1.82;
    }

    #top-settings-holder > .drawer > .drawer-toggle {
        padding-inline: 1px;
    }

    #top-settings-holder > .drawer > .drawer-toggle .drawer-icon {
        font-size: 7px;
    }

    #send_form {
        min-height: var(--bottomFormBlockSize);
        padding-block: 3px;
        border-radius: var(--theme-radius-small);
    }

    #nonQRFormItems {
        flex-wrap: nowrap;
    }

    #leftSendForm,
    #rightSendForm {
        width: auto;
        flex-wrap: nowrap;
    }

    #send_textarea {
        min-width: 0;
        min-height: 36px;
        max-height: 96px;
        padding: 6px 8px;
        font-size: 16px !important;
        line-height: 1.35;
    }

    #send_textarea::placeholder { font-size: 16px; }

    .drawer-content {
        max-width: 100%;
        border-radius: 0 0 var(--theme-radius-small) var(--theme-radius-small);
    }

    #left-nav-panel :is(#openai_api-presets, #textgenerationwebui_api-presets) select {
        width: 100%;
    }

    /* 手机 Chromium 会把预设 select 重新绘制成灰面；以真实文本补全预设 ID 覆盖其内部表面。 */
    #left-nav-panel :is(#settings_preset, #settings_preset_novel, #settings_preset_openai, #settings_preset_textgenerationwebui) {
        color: var(--theme-text-primary);
        -webkit-text-fill-color: var(--theme-text-primary);
        border-color: var(--theme-border-strong);
        background-color: var(--theme-surface);
        box-shadow: inset 0 0 0 100vmax var(--theme-surface);
        opacity: 1;
        filter: none;
        text-shadow: none;
    }
}

/* 远程素材与字体失败不改变几何：原生 Font Awesome 入口仍保留在同一触发器中。 */
@media (forced-colors: active) {
    #top-settings-holder > .drawer > .drawer-toggle .drawer-icon {
        background-image: none;
        font-size: var(--topBarIconSize);
    }

    #top-settings-holder > .drawer > .drawer-toggle .drawer-icon::before {
        display: inline-block;
    }
}

@media (prefers-reduced-motion: reduce) {
    #top-settings-holder > .drawer > .drawer-toggle,
    #send_form,
    #chat .mes {
        transition: none;
    }
}
